def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    size = len(ranks)
    bit = [0] * (size + 1)
    result = []

    for i, value in enumerate(a):
        if i > k:
            rank = ranks[a[i - k - 1]]
            while rank <= size:
                bit[rank] -= 1
                rank += rank & -rank

        rank = ranks[value]
        prefix = 0
        j = rank
        while j:
            prefix += bit[j]
            j -= j & -j

        result.append(min(i, k) - prefix)

        while rank <= size:
            bit[rank] += 1
            rank += rank & -rank

    return result
